#!/usr/bin/env python3
"""The tutorial series: narration and storyboard for every video. Run it to (re)write each video's script.json.

    python3 tutorials/series.py                    # Kokoro narration (the default)
    python3 tutorials/series.py --engine breeze    # Breeze narration (see tutorials/voice/README.md for its licence)

Each beat is  B(say, visual, cap=None, after=None):
  say     what the voice reads. Numbers are written as words, acronyms spelled out ("C S V"), no symbols.
  visual  the storyboard note the scene-coding workers are briefed from, with the cue word for each reveal.
  cap     the caption, when it should show digits or symbols that the voice reads as words.
  after   seconds of silence after the beat (a pause for the viewer).
Numbers are from the app's own engine (tutorials/common/pvdata.py) or from the validation and dataset runs shown in
docs/screenshots, so they match what the viewer will see when they try it.
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
VOICE = "af_heart"


def B(say, visual, cap=None, after=None):
    beat = {"say": say, "visual": visual}
    if cap:
        beat["cap"] = cap
    if after:
        beat["after"] = after
    return beat


def S(id_, cls, title, *beats):
    return {"id": id_, "class": cls, "title": title, "mode": "reveal", "beats": list(beats)}


