def main():
    engine = sys.argv[sys.argv.index("--engine") + 1] if "--engine" in sys.argv else "kokoro"
    if engine not in ("kokoro", "breeze"):
        sys.exit("--engine is kokoro or breeze")
    for name, video in VIDEOS.items():
        folder = ROOT / name
        folder.mkdir(exist_ok=True)
        script = {"title": video["title"], "label": video["label"], "voice": VOICE, "speed": 0.92, "gap": 0.42, "scenes": video["scenes"]}
        if engine == "breeze":
            script["engine"] = "breeze"
        (folder / "script.json").write_text(json.dumps(script, indent=2, ensure_ascii=False) + "\n")
        beats = sum(len(s["beats"]) for s in video["scenes"])
        words = sum(len(b["say"].split()) for s in video["scenes"] for b in s["beats"])
        print(f"{name} ({engine}): {len(video['scenes'])} scenes, {beats} beats, {words} words (about {words / 2.4 / 60:.1f} min)")


if __name__ == "__main__":
    main()
